import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
lines = [
 "बार बार प्यास? बार बार पेशाब? घाव देर से भरता है? हो सकता है शुगर बढ़ी हुई हो. आज शुक्रवार की हेल्थ टिप में जानिए, फास्टिंग, पी पी, और जी टी टी शुगर टेस्ट. आखिर तक देखिए.",
 "भारत में दस करोड़ से ज़्यादा लोगों को डायबिटीज़ है, यानी लगभग ग्यारह प्रतिशत. और करीब साढ़े तेरह करोड़ लोग प्री डायबिटीज़ में हैं. बहुत से लोगों को पता ही नहीं होता.",
 "शुगर के तीन मुख्य टेस्ट हैं. फास्टिंग, यानी खाली पेट. पी पी, यानी खाना खाने के दो घंटे बाद. और जी टी टी, यानी ग्लूकोज़ पीने के बाद की जांच.",
 "फास्टिंग शुगर के लिए, कम से कम आठ घंटे कुछ न खाएं. सादा पानी पी सकते हैं. सौ से कम, सामान्य. सौ से एक सौ पच्चीस, प्री डायबिटीज़. एक सौ छब्बीस या ज़्यादा, डायबिटीज़ हो सकती है.",
 "पी पी शुगर, खाना शुरू करने के ठीक दो घंटे बाद होती है. अपना रोज़ का सामान्य खाना खाएं. आमतौर पर एक सौ चालीस से कम सामान्य माना जाता है. लैब के हिसाब से रेंज थोड़ी बदल सकती है.",
 "जी टी टी में, खाली पेट सैंपल के बाद, पचहत्तर ग्राम ग्लूकोज़ पानी में घोलकर पिलाया जाता है. दो घंटे बाद फिर सैंपल. एक सौ चालीस से कम, सामान्य. एक सौ चालीस से एक सौ निन्यानवे, प्री डायबिटीज़. दो सौ या ज़्यादा, डायबिटीज़. इन दो घंटों में कुछ न खाएं, और आराम से बैठें.",
 "प्रेग्नेंसी में भी शुगर जांच ज़रूरी है. भारत में डी आई पी एस आई टेस्ट होता है. पचहत्तर ग्राम ग्लूकोज़, और खाली पेट होना ज़रूरी नहीं. दो घंटे बाद एक सौ चालीस या ज़्यादा, तो गर्भावस्था की डायबिटीज़. पहली जांच पहली विज़िट पर, और फिर चौबीस से अट्ठाईस हफ्ते में.",
 "किसे जांच करानी चाहिए? तीस साल से ऊपर हर व्यक्ति. परिवार में डायबिटीज़ हो. वज़न ज़्यादा हो, या बी पी हो. पी सी ओ डी हो. या बार बार प्यास, पेशाब, और थकान हो. और याद रखें, एक रिपोर्ट से नहीं, डॉक्टर दोबारा जांच से ही पक्का करते हैं.",
 "याद रखें, कोई भी दवा सिर्फ डॉक्टर की सलाह से ही लें. आपने आखिरी बार शुगर कब चेक करवाई थी? कमेंट में बताइए, और शेयर करें. और ज़्यादा जानकारी के लिए, हमारा फेसबुक पेज और यूट्यूब चैनल फॉलो करें. हेल्थ टेस्ट सिम्प्लिफाइड. ध्यान दें, यह वीडियो केवल बीमारियों और टेस्ट के बारे में सामान्य जानकारी के लिए है. जानकारी समय के साथ बदल सकती है. अपनी स्थिति को इस वीडियो से न जोड़ें. हमेशा अपने डॉक्टर से ही सलाह लें, और उन्हीं की सलाह मानें.",
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/sgr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/sg_{i}.wav"],check=True); f=f"/tmp/sg_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/sg_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
